        scope["code"] = String(_root["GridXSize"]) + "x" + String(_root["GridYSize"]);
        // ^ Stats like size and name an bg
        scope["code"] += "~" + _root["CompactNumbers"](_root["TileArray"]);
        // ^ Tile arry compacted
        scope["code"] += "~";
        for (scope["i"] = 0; scope["i"] < _root["LDItemArray"]["length"]; scope["i"]++) {
            if (strictNotEquals(scope["i"], 0)) {
                scope["code"] += "|";
            }
            scope["code"] += "" + _root["LDItemArray"][scope["i"]];
        }
        scope["code"] += "~" + _root["LDMusic"];
        scope["code"] += "~" + _root["LDCourseBG"];
        scope["code"] += "~" + escape(_root["LDCourseName"]);
        // ^ Item Array
        trace("Timed: " + (getTimer() - scope["time"]) + " ms");
        return (scope["code"]);
