    _root["CalculateFilesInfo"] = scope.function([](Activation& scope) -> Value {
        //
        _root["MaxStarCoins"] = 0;
        for (scope["i"] = 0; scope["i"] < 4; scope["i"]++) {
            if (scope["i"] == 0) {
                scope["file"] = "A";
            }
            if (scope["i"] == 1) {
                scope["file"] = "B";
            }
            if (scope["i"] == 2) {
                scope["file"] = "C";
            }
            if (scope["i"] == 3) {
                scope["file"] = "D";
            }
            //
            scope["count"] = 1;
            _root["File" + scope["file"] + "TotalStars"] = 0;
            while (strictNotEquals(_root["File" + scope["file"] + "Star"][scope["count"]], undefined)) {
                if (_root["File" + scope["file"] + "Star"][scope["count"]] == true) {
                    _root["File" + scope["file"] + "TotalStars"]++;
                }
                scope["count"]++;
            }
            //
            scope["count"] = 1;
            _root["File" + scope["file"] + "TotalStarCoins"] = 0;
            while (strictNotEquals(_root["File" + scope["file"] + "StarCoin"][scope["count"]], undefined)) {
                if (_root["File" + scope["file"] + "StarCoin"][scope["count"]] == true) {
                    _root["File" + scope["file"] + "TotalStarCoins"]++;
                }
                scope["count"]++;
            }
            if (_root["File" + scope["file"] + "TotalStarCoins"] > _root["MaxStarCoins"]) {
                _root["MaxStarCoins"] = _root["File" + scope["file"] + "TotalStarCoins"];
            }
        }
        trace(_root["MaxStarCoins"]);
        //
        return undefined;
    });
