// <main> / layer 'Layer 3' / frame 4
void frame_0_10(Activation& scope) {
    _root["FallSquish"] = scope.function([](Activation& scope) -> Value {
        {
            TellTarget tellTarget1(scope, _root["Course"]["Char"]);
            scope["nohurt"] = false;
            if ((scope["attack"] == false || scope["attackFrame"] == "land") && scope["fallingyspeed"] >= 14.5 && scope["yspeed"] > 10) {
                scope["hurtfall"] = Math["round"]((scope["fallingyspeed"] - 14.5) * 3);
            } else if (scope["fallingyspeed"] >= 21 && scope["yspeed"] > 10 && scope["attackFrame"] == "Ground") {
                scope["hurtfall"] = Math["round"]((scope["fallingyspeed"] - 23) / 2);
            } else {
                scope["nohurt"] = true;
            }
            // else if (fallingyspeed>=16 && yspeed>10 && attackFrame == "Dive") {
            //hurtfall = Math.round((fallingyspeed-16)/2);
            //}
            if (scope["fallingyspeed"] >= 15 && scope["yspeed"] > 10 && scope["hurtfallcount"] > 3 && strictNotEquals(scope["nohurt"], true)) {
                scope["hurtfall"] = Math["max"](scope["hurtfall"], 1);
                scope["hurtfall"] = Math["min"](scope["hurtfall"], 4);
                _root["CharHP"] -= scope["hurtfall"];
                scope["attack"] = true;
                scope["attackFrame"] = "Squish";
            }
            scope["hurtfall"] = 0;
            scope["fallingyspeed"] = 0;
        }
        return undefined;
    });
}

